import requests

def fetch_models(max_pages=10):
    models = []
    seen = set()
    cursor = None
    for _ in range(max_pages):
        params = {} if cursor is None else {"cursor": cursor}
        resp = requests.get("https://api.dojo.dev/models", params=params)
        body = resp.json()
        for m in body["models"]:
            if m["id"] not in seen:
                seen.add(m["id"])
                models.append(m)
        cursor = body["next_cursor"]
        if cursor is None:
            return models
    raise RuntimeError(f"hit the limit of {max_pages} pages without finishing")

