import requests
import time

class PermanentError(Exception):
    def __init__(self, status):
        super().__init__(f"permanent error: status {status}")
        self.status = status

def fetch_with_backoff(path, max_attempts, base):
    for attempt in range(max_attempts):
        resp = requests.get("https://api.dojo.dev" + path)
        if resp.status_code == 200:
            return resp.json()
        if resp.status_code not in (429, 500):
            raise PermanentError(resp.status_code)
        if attempt < max_attempts - 1:
            if resp.status_code == 429:
                time.sleep(int(resp.headers["Retry-After"]))
            else:
                time.sleep(base * (2 ** attempt))
    return None

