import requests
import time

def fetch_models_robust(max_total_attempts, max_pages=10):
    models = []
    seen = set()
    cursor = None
    attempts = 0
    for _ in range(max_pages):
        while True:
            attempts += 1
            if attempts > max_total_attempts:
                raise RuntimeError("attempt budget exhausted")
            params = {} if cursor is None else {"cursor": cursor}
            resp = requests.get("https://api.dojo.dev/models", params=params)
            if resp.status_code == 200:
                break
            if resp.status_code == 429:
                time.sleep(int(resp.headers["Retry-After"]))
            elif resp.status_code == 500:
                pass
            else:
                raise RuntimeError(f"unexpected status: {resp.status_code}")
        body = resp.json()
        for m in body["models"]:
            if m["id"] not in seen:
                seen.add(m["id"])
                models.append(m)
        nxt = body["next_cursor"]
        if nxt is None or nxt == cursor:
            return models
        cursor = nxt
    raise RuntimeError(f"hit the limit of {max_pages} pages")

