def chunks_lazy(documents, size, overlap):
    step = size - overlap
    index = 0
    for doc in documents:
        words = doc["text"].split()
        i = 0
        while i < len(words):
            yield {
                "text": " ".join(words[i:i + size]),
                "doc": doc["name"],
                "index": index,
            }
            index += 1
            if i + size >= len(words):
                break
            i += step

