import numpy as np
from openai import OpenAI


def embed(text):
    client = OpenAI()
    resp = client.embeddings.create(model="mock-embed", input=text)
    return resp.data[0].embedding


def cosine(a, b):
    a = np.array(a, dtype=float)
    b = np.array(b, dtype=float)
    norm_a = np.linalg.norm(a)
    norm_b = np.linalg.norm(b)
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return float(np.dot(a, b) / (norm_a * norm_b))


def search(matrix, metadata, question, k, threshold):
    q = embed(question)
    scores = [cosine(row, q) for row in matrix]
    order = np.argsort(-np.array(scores), kind="stable")
    results = []
    for i in order:
        i = int(i)
        if len(results) >= k:
            break
        if scores[i] < threshold:
            break
        results.append({
            "doc": metadata[i]["doc"],
            "text": metadata[i]["text"],
            "score": scores[i],
        })
    return results

def chunk_documents(documents, size, overlap):
    if overlap >= size:
        raise ValueError("overlap must be smaller than size")
    chunks = []
    step = size - overlap
    for doc in documents:
        words = doc["text"].split()
        if not words:
            continue
        i = 0
        while i < len(words):
            chunks.append({
                "text": " ".join(words[i:i + size]),
                "doc": doc["name"],
                "index": len(chunks),
            })
            if i + size >= len(words):
                break
            i += step
    return chunks

