def build_index_dedupe(chunks, max_sim=0.95):
    vectors = []
    metadata = []
    for c in chunks:
        v = embed(c["text"])
        duplicate = False
        for u in vectors:
            if cosine(u, v) > max_sim:
                duplicate = True
                break
        if not duplicate:
